CREATE COLUMN TABLE "TEST_AP"."GPC1" ("AbsId" INTEGER CS_INT NOT NULL , "BPLId" INTEGER CS_INT NOT NULL , "State" NVARCHAR(3) NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , PRIMARY KEY ("AbsId", "BPLId", "State")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "GPC1_CARD_CODE" ON "TEST_AP"."GPC1" ( "CardCode" ASC )